<?php require 'includes/functions.php';$u=require_user();$pageTitle='My account';$orders=query('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC',[$u['id']])->fetchAll();require 'includes/header.php';?><section class="container section"><div class="section-head"><div><span class="eyebrow">YOUR ACCOUNT</span><h1>Hello, <?=e($u['username'])?>.</h1><p class="muted"><?=e($u['email'])?></p></div><form method="post" action="<?=e(url('auth/logout.php'))?>"><?php csrf();?><button class="outline">Sign out</button></form></div><div class="actions"><a class="button" href="<?=e(url('new-arrivals.php'))?>">Continue shopping</a><?php if(!empty($_SESSION['cart'])):?><a class="button outline" href="<?=e(url('checkout.php'))?>">Checkout your bag</a><?php endif;?></div><h2>Your orders</h2><?php if(!$orders):?><div class="panel"><p>No orders yet. Your next signature scent is waiting.</p></div><?php endif;foreach($orders as $o):?><article class="panel order"><div class="section-head"><h3>Order #<?=$o['id']?></h3><span class="badge"><?=e($o['status'])?></span></div><p class="muted"><?=e($o['created_at'])?> · Cash on delivery · <?=money($o['total'])?></p><ul><?php foreach(query('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll() as $item):?><li><?=e($item['product_name'])?> × <?=$item['quantity']?> — <?=money($item['unit_price']*$item['quantity'])?></li><?php endforeach;?></ul><p class="small">Delivery to <?=e($o['customer_name'].', '.$o['address'])?></p></article><?php endforeach;?></section><?php require 'includes/footer.php';?>
